// Calculate aggregate metrics
const businesses = $input.all();
const now = new Date();
const totalWhatsApp = businesses.reduce((sum, b) => sum + parseInt(b.json.whatsapp_used), 0);
const totalContent = businesses.reduce((sum, b) => sum + parseInt(b.json.content_used), 0);
const totalVoice = businesses.reduce((sum, b) => sum + parseInt(b.json.voice_used), 0);
const totalAudit = businesses.reduce((sum, b) => sum + parseInt(b.json.audit_used), 0);
return [{
  json: {
    report_date: now.toISOString(),
    total_businesses: businesses.length,
    total_whatsapp_messages: totalWhatsApp,
    total_content_generations: totalContent,
    total_voice_calls: totalVoice,
    total_audits: totalAudit,
    top_10_businesses: businesses
      .sort((a, b) => (parseInt(b.json.whatsapp_used) + parseInt(b.json.content_used)) - (parseInt(a.json.whatsapp_used) + parseInt(a.json.content_used)))
      .slice(0, 10)
      .map(b => ({ name: b.json.name, tier: b.json.subscription_tier, usage: parseInt(b.json.whatsapp_used) + parseInt(b.json.content_used) }))
  }
}];

